package io.turboio.enhanced;

import java.io.*;
import java.util.*;
import java.util.concurrent.*;
import org.json.*;

/** Minimal source-compatible client for Paseo daemon protocol v1. The daemon is not modified. */
final class PaseoClient implements Closeable {
    static final class Agent {final String id,title,provider,status,cwd,updatedAt;Agent(String i,String t,String p,String s,String c,String u){id=i;title=t;provider=p;status=s;cwd=c;updatedAt=u;}String label(){return title.isEmpty()?id.substring(0,Math.min(8,id.length())):title;}}
    static final class Workspace {final String id,name,project,directory,status;Workspace(String i,String n,String p,String d,String s){id=i;name=n;project=p;directory=d;status=s;}String label(){return name.isEmpty()?project:name;}}
    static final class Finish {final String status,lastMessage,error;Finish(String s,String m,String e){status=s;lastMessage=m;error=e;}}
    private final PaseoConfigStore.Config config;private final Map<String,ArrayBlockingQueue<JSONObject>> pending=new ConcurrentHashMap<>();private volatile PaseoWebSocket ws;private volatile boolean connected,closed;private volatile String error="";private CountDownLatch hello;
    PaseoClient(PaseoConfigStore.Config config){this.config=config;}
    String state(){return connected?"已连接":error.isEmpty()?"未连接":"未连接："+error;}
    synchronized void connect()throws Exception{if(connected)return;PaseoWebSocket created=PaseoWebSocket.connect(config.url,config.password,8000);CountDownLatch ready=new CountDownLatch(1);if(closed){created.close();throw new IOException("客户端已关闭");}ws=created;hello=ready;error="";Thread reader=new Thread(()->readLoop(created),"Paseo-reader");reader.setDaemon(true);reader.start();JSONObject h=new JSONObject().put("type","hello").put("clientId",config.clientId).put("clientType","mobile").put("protocolVersion",1).put("appVersion","rayneo-bridge-1").put("capabilities",new JSONObject().put("timelineNotifications",true));created.sendText(h.toString());if(!ready.await(10,TimeUnit.SECONDS)){created.close();throw new IOException("Paseo hello 超时");}connected=true;}
    List<Agent> listAgents(int limit)throws Exception{JSONObject req=base("fetch_agents_request").put("scope","active").put("sort",new JSONArray().put(new JSONObject().put("key","updated_at").put("direction","desc"))).put("page",new JSONObject().put("limit",Math.max(1,Math.min(50,limit))));JSONObject p=request(req,"fetch_agents_response",15000);JSONArray entries=p.optJSONArray("entries");List<Agent> out=new ArrayList<>();if(entries!=null)for(int i=0;i<entries.length();i++){JSONObject a=entries.getJSONObject(i).getJSONObject("agent");out.add(agent(a));}return out;}
    List<Workspace> listWorkspaces(int limit)throws Exception{JSONObject req=base("fetch_workspaces_request").put("sort",new JSONArray().put(new JSONObject().put("key","activity_at").put("direction","desc"))).put("page",new JSONObject().put("limit",Math.max(1,Math.min(50,limit))));JSONObject p=request(req,"fetch_workspaces_response",15000);JSONArray entries=p.optJSONArray("entries");List<Workspace> out=new ArrayList<>();if(entries!=null)for(int i=0;i<entries.length();i++){JSONObject w=entries.optJSONObject(i);if(w==null)continue;String directory=text(w,"workspaceDirectory");if(directory.isEmpty())continue;out.add(new Workspace(text(w,"id"),text(w,"name"),text(w,"projectDisplayName"),directory,text(w,"status")));}return out;}
    Agent createCodex(Workspace workspace)throws Exception{JSONObject config=new JSONObject().put("provider","codex").put("cwd",workspace.directory);JSONObject req=base("create_agent_request").put("config",config).put("workspaceId",workspace.id).put("labels",new JSONObject());JSONObject p=request(req,"status",30000);if("agent_create_failed".equals(p.optString("status")))throw new IOException(p.optString("error","Paseo 创建会话失败"));if(!"agent_created".equals(p.optString("status")))throw new IOException("Paseo 创建会话响应异常");JSONObject a=p.optJSONObject("agent");if(a==null)throw new IOException("Paseo 未返回新会话");return agent(a);}
    String lastAssistant(String agentId)throws Exception{JSONObject req=base("fetch_agent_timeline_request").put("agentId",agentId).put("direction","tail").put("limit",40).put("projection","projected");JSONObject p=request(req,"fetch_agent_timeline_response",15000);if(!p.isNull("error"))throw new IOException(p.optString("error"));JSONArray e=p.optJSONArray("entries");if(e!=null)for(int i=e.length()-1;i>=0;i--){JSONObject item=e.getJSONObject(i).optJSONObject("item");if(item!=null&&"assistant_message".equals(item.optString("type"))&&!item.optString("text").trim().isEmpty())return item.optString("text");}return"没有找到助手回复";}
    void send(String agentId,String text)throws Exception{JSONObject req=base("send_agent_message_request").put("agentId",agentId).put("text",text).put("messageId",UUID.randomUUID().toString());JSONObject p=request(req,"send_agent_message_response",20000);if(!p.optBoolean("accepted"))throw new IOException(p.optString("error","Paseo 拒绝了消息"));}
    Finish waitForFinish(String agentId,long timeoutMs)throws Exception{JSONObject req=base("wait_for_finish_request").put("agentId",agentId).put("timeoutMs",timeoutMs);JSONObject p=request(req,"wait_for_finish_response",timeoutMs+10000);return new Finish(p.optString("status"),p.optString("lastMessage"),p.optString("error"));}
    void cancel(String agentId)throws Exception{JSONObject p=request(base("cancel_agent_request").put("agentId",agentId),"cancel_agent_response",15000);if(!p.isNull("error"))throw new IOException(p.optString("error"));}
    private JSONObject base(String type)throws JSONException{return new JSONObject().put("type",type).put("requestId",UUID.randomUUID().toString());}
    private JSONObject request(JSONObject message,String expected,long timeout)throws Exception{connect();String id=message.getString("requestId");ArrayBlockingQueue<JSONObject> q=new ArrayBlockingQueue<>(1);pending.put(id,q);try{PaseoWebSocket socket=ws;if(socket==null)throw new IOException("Paseo 未连接");socket.sendText(new JSONObject().put("type","session").put("message",message).toString());JSONObject response=q.poll(timeout,TimeUnit.MILLISECONDS);if(response==null)throw new IOException("Paseo 请求超时");if("rpc_error".equals(response.optString("type")))throw new IOException(response.optJSONObject("payload").optString("error","Paseo RPC 失败"));if(!expected.equals(response.optString("type")))throw new IOException("Paseo 响应类型异常");return response.getJSONObject("payload");}finally{pending.remove(id);}}
    private void readLoop(PaseoWebSocket socket){try{while(!closed){JSONObject envelope=new JSONObject(socket.readText());if("pong".equals(envelope.optString("type")))continue;if(!"session".equals(envelope.optString("type")))continue;JSONObject m=envelope.optJSONObject("message");if(m==null)continue;JSONObject p=m.optJSONObject("payload");if("status".equals(m.optString("type"))&&p!=null&&"server_info".equals(p.optString("status"))){CountDownLatch l=hello;if(l!=null)l.countDown();continue;}String id=p==null?"":p.optString("requestId");ArrayBlockingQueue<JSONObject> q=pending.get(id);if(q!=null)q.offer(m);}}catch(Exception e){error=e.getMessage()==null?e.getClass().getSimpleName():e.getMessage();}finally{connected=false;if(ws==socket)ws=null;JSONObject failure=transportFailure();for(ArrayBlockingQueue<JSONObject> q:pending.values())q.offer(failure);socket.close();}}
    private static JSONObject transportFailure(){try{return new JSONObject().put("type","rpc_error").put("payload",new JSONObject().put("error","Paseo 连接已断开"));}catch(JSONException impossible){throw new AssertionError(impossible);}}
    private static Agent agent(JSONObject a){return new Agent(text(a,"id"),text(a,"title"),text(a,"provider"),text(a,"status"),text(a,"cwd"),text(a,"updatedAt"));}
    private static String text(JSONObject value,String key){Object raw=value.opt(key);return raw==null||raw==JSONObject.NULL?"":String.valueOf(raw);}
    public synchronized void close(){closed=true;connected=false;if(ws!=null)ws.close();ws=null;}
}
